-- ============================================
-- NURSE'S ROLE IN INFORMED CONSENT - 100 QUESTIONS
-- ============================================
-- Run this AFTER ADD-SUBJECTS-TOPICS-TABLE.sql
-- All 100 questions for Topic 2: Nurse's Role in Informed Consent

-- Delete any existing questions for this topic to avoid duplicates
DELETE FROM test_questions 
WHERE test_id = '00000000-0000-0000-0000-000000000001' 
  AND topic_id = '20000000-0000-0000-0000-000000000002';

-- Insert 100 Informed Consent Questions (display_order 1-100 for this topic)
INSERT INTO test_questions (test_id, topic_id, question_stem, options, correct_answers, is_multiple_choice, rationale, category, display_order) VALUES

-- Questions 1-10: Nurse Boundaries & Provider Role
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A nurse begins explaining the risks of a procedure in detail because the patient "looks nervous." What is the best response?', '[{"id":"a","text":"Continue; the nurse is the patient educator"},{"id":"b","text":"Stop; only the provider may obtain informed consent"},{"id":"c","text":"Continue; nurses may obtain consent if provider is busy"},{"id":"d","text":"Proceed only if the patient signs voluntarily"}]'::jsonb, ARRAY['b'], false, 'Only the provider (MD/NP/PA) may obtain informed consent by explaining risks, benefits, and alternatives. The nurse educates and reinforces but does not obtain consent.', 'Informed Consent', 1),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'After the provider explains the procedure, the patient asks the nurse: "What are the alternatives?" What should the nurse do first?', '[{"id":"a","text":"Explain all alternatives in depth"},{"id":"b","text":"Tell the patient alternatives are not required"},{"id":"c","text":"Reinforce that the provider will clarify alternatives and notify the provider"},{"id":"d","text":"Ask the family to explain alternatives"}]'::jsonb, ARRAY['c'], false, 'The nurse should reinforce provider explanations but must notify the provider when patients have unanswered questions about alternatives.', 'Informed Consent', 2),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The patient states: "I don''t really understand, but I''ll sign so we can get this over with." The nurse should:', '[{"id":"a","text":"Witness the signature because the patient agreed"},{"id":"b","text":"Provide detailed explanation and proceed"},{"id":"c","text":"Stop the process and notify the provider"},{"id":"d","text":"Ask the patient to sign later without delaying procedure"}]'::jsonb, ARRAY['c'], false, 'If the patient does not understand, consent is invalid. The nurse must stop and notify the provider.', 'Informed Consent', 3),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which action is within the nurse''s educator role regarding informed consent?', '[{"id":"a","text":"Obtain the consent signature"},{"id":"b","text":"Explain risks and alternatives independently"},{"id":"c","text":"Encourage questions and reinforce the provider''s explanation"},{"id":"d","text":"Decide whether the patient should proceed"}]'::jsonb, ARRAY['c'], false, 'The nurse educator role includes reinforcing provider explanations, encouraging questions, and checking understanding—not obtaining consent.', 'Informed Consent', 4),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse suspects the patient is being pressured by a spouse to sign consent. Which role is most directly involved?', '[{"id":"a","text":"Witness"},{"id":"b","text":"Advocate"},{"id":"c","text":"Educator"},{"id":"d","text":"Recorder"}]'::jsonb, ARRAY['b'], false, 'The advocate role involves ensuring the patient is not coerced or pressured and signing voluntarily.', 'Informed Consent', 5),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which situation makes consent invalid according to the document?', '[{"id":"a","text":"Patient is anxious but oriented"},{"id":"b","text":"Patient has questions"},{"id":"c","text":"Patient is under sedation"},{"id":"d","text":"Patient requests more time"}]'::jsonb, ARRAY['c'], false, 'Sedation impairs decision-making capacity. Consent signed under sedation or opioids is invalid.', 'Informed Consent', 6),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient is alert, oriented, and voluntarily signs consent. Which nurse role is appropriate at the time of signing?', '[{"id":"a","text":"Obtain consent"},{"id":"b","text":"Explain procedure"},{"id":"c","text":"Witness signature and verify competency/voluntary signing"},{"id":"d","text":"Decide if patient should proceed"}]'::jsonb, ARRAY['c'], false, 'The nurse witnesses the signature and verifies the patient is alert, oriented, and signing voluntarily.', 'Informed Consent', 7),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient received opioids and appears drowsy. The provider asks the nurse to "just have them sign." The nurse should:', '[{"id":"a","text":"Witness signature if patient can hold a pen"},{"id":"b","text":"Allow signature because provider requested it"},{"id":"c","text":"Refuse and delay the procedure because consent is invalid under sedation/opioids"},{"id":"d","text":"Ask family to sign instead"}]'::jsonb, ARRAY['c'], false, 'Consent under sedation or opioids is invalid. The nurse must refuse to witness and delay the procedure.', 'Informed Consent', 8),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient says: "I''m not sure I want this anymore." The nurse''s best action is:', '[{"id":"a","text":"Reassure and proceed"},{"id":"b","text":"Stop the process and notify the provider"},{"id":"c","text":"Have the patient sign but mark \"hesitant\""},{"id":"d","text":"Ask family to convince the patient"}]'::jsonb, ARRAY['b'], false, 'Any hesitancy or uncertainty requires stopping the process and notifying the provider.', 'Informed Consent', 9),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which professional may obtain informed consent?', '[{"id":"a","text":"RN"},{"id":"b","text":"CNA"},{"id":"c","text":"Provider (MD/NP/PA)"},{"id":"d","text":"Unit clerk"}]'::jsonb, ARRAY['c'], false, 'Only the provider (physician, nurse practitioner, or physician assistant) may obtain informed consent.', 'Informed Consent', 10),

-- Questions 11-20: Language Barriers, Documentation & Patient Questions
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The patient speaks limited English. The family insists they can translate. The nurse should:', '[{"id":"a","text":"Allow family to interpret"},{"id":"b","text":"Use a licensed medical interpreter"},{"id":"c","text":"Ask a bilingual staff member who is available"},{"id":"d","text":"Proceed if the patient nods \"yes\""}]'::jsonb, ARRAY['b'], false, 'A licensed medical interpreter must be used to ensure accurate communication and patient understanding.', 'Informed Consent', 11),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is required documentation for informed consent support?', '[{"id":"a","text":"Nurse''s opinion that patient understood"},{"id":"b","text":"Date/time of consent + summary of education + questions and responses + competency verification"},{"id":"c","text":"Only patient signature"},{"id":"d","text":"Only provider note"}]'::jsonb, ARRAY['b'], false, 'Complete documentation includes date/time, education summary, questions/responses, and competency verification.', 'Informed Consent', 12),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The patient asks: "What happens if I refuse?" The nurse should:', '[{"id":"a","text":"Explain refusal consequences independently"},{"id":"b","text":"Encourage refusal if patient is uncertain"},{"id":"c","text":"Advocate for patient''s right to refuse and notify provider for clarification"},{"id":"d","text":"Tell patient refusal is not allowed after admission"}]'::jsonb, ARRAY['c'], false, 'The nurse advocates for the patient''s right to refuse and notifies the provider to clarify consequences.', 'Informed Consent', 13),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse is witnessing consent. Which assessment matters MOST at that moment?', '[{"id":"a","text":"Pulse rate"},{"id":"b","text":"Alert and oriented status"},{"id":"c","text":"IV patency"},{"id":"d","text":"Temperature"}]'::jsonb, ARRAY['b'], false, 'Mental competency (alert and oriented status) is essential when witnessing consent.', 'Informed Consent', 14),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'During the consent process, the patient appears confused. The nurse should:', '[{"id":"a","text":"Witness signature anyway if family agrees"},{"id":"b","text":"Alert the provider and stop the process"},{"id":"c","text":"Ask the patient to sign quickly to avoid delay"},{"id":"d","text":"Explain procedure until confusion resolves"}]'::jsonb, ARRAY['b'], false, 'Confusion indicates lack of capacity. The nurse must stop and alert the provider.', 'Informed Consent', 15),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A nurse reinforces the provider''s education using visual aids. This belongs to which role?', '[{"id":"a","text":"Educator"},{"id":"b","text":"Advocate"},{"id":"c","text":"Witness"},{"id":"d","text":"Legal representative"}]'::jsonb, ARRAY['a'], false, 'Using visual aids to reinforce provider education is part of the educator role.', 'Informed Consent', 16),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which statement by the nurse is most appropriate when the patient has unanswered questions?', '[{"id":"a","text":"\"I can explain everything; the provider is busy.\""},{"id":"b","text":"\"Sign now; you can ask later.\""},{"id":"c","text":"\"Let''s pause—I''ll notify the provider so your questions can be addressed.\""},{"id":"d","text":"\"Your family can explain.\""}]'::jsonb, ARRAY['c'], false, 'The nurse should pause and notify the provider when the patient has unanswered questions.', 'Informed Consent', 17),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'What must the nurse do if the patient "still doesn''t understand" after reinforcement?', '[{"id":"a","text":"Proceed to signature"},{"id":"b","text":"Notify the provider"},{"id":"c","text":"Have the family interpret"},{"id":"d","text":"Ask another nurse to witness"}]'::jsonb, ARRAY['b'], false, 'If the patient still does not understand after nursing reinforcement, the provider must be notified.', 'Informed Consent', 18),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Informed consent includes which provider explanation elements?', '[{"id":"a","text":"Only risks"},{"id":"b","text":"Procedure, risks, benefits, alternatives"},{"id":"c","text":"Procedure only"},{"id":"d","text":"Benefits only"}]'::jsonb, ARRAY['b'], false, 'Informed consent requires explanation of procedure, risks, benefits, and alternatives.', 'Informed Consent', 19),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is a key part of the nurse advocate role?', '[{"id":"a","text":"Explain alternatives"},{"id":"b","text":"Confirm patient is not pressured/coerced"},{"id":"c","text":"Obtain signature"},{"id":"d","text":"Decide whether procedure is necessary"}]'::jsonb, ARRAY['b'], false, 'The advocate role includes ensuring the patient is not pressured or coerced.', 'Informed Consent', 20),

-- Questions 21-30: Nurse Boundaries & Special Situations
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is the nurse''s correct boundary?', '[{"id":"a","text":"Nurse can obtain consent if provider delegated"},{"id":"b","text":"Nurse can witness but not provide the \"informed explanation\" as consent obtainer"},{"id":"c","text":"Nurse can replace interpreter if fluent"},{"id":"d","text":"Nurse can proceed if patient is sedated but family agrees"}]'::jsonb, ARRAY['b'], false, 'The nurse witnesses signatures but does not obtain informed consent—that is the provider''s role.', 'Informed Consent', 21),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A minor (<18) needs surgery. What is required (per document)?', '[{"id":"a","text":"RN consent"},{"id":"b","text":"Guardian consent (with exceptions noted)"},{"id":"c","text":"Peer consent"},{"id":"d","text":"Consent is implied always"}]'::jsonb, ARRAY['b'], false, 'Minors require guardian consent, with specific exceptions (emancipated minors, emergencies).', 'Informed Consent', 22),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is TRUE about emergencies?', '[{"id":"a","text":"Consent is never needed"},{"id":"b","text":"Consent must always be written"},{"id":"c","text":"Consent may be implied if unconscious and no surrogate available"},{"id":"d","text":"Family must sign no matter what"}]'::jsonb, ARRAY['c'], false, 'In emergencies, consent may be implied if the patient is unconscious and no surrogate is available.', 'Informed Consent', 23),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient is unsure and hesitant but says "Okay." The nurse should:', '[{"id":"a","text":"Proceed and witness signature"},{"id":"b","text":"Ask the provider to return and clarify due to hesitancy"},{"id":"c","text":"Ask family to encourage patient"},{"id":"d","text":"Tell patient hesitancy is normal and ignore it"}]'::jsonb, ARRAY['b'], false, 'Any hesitancy requires the provider to return and clarify before proceeding.', 'Informed Consent', 24),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is an NCLEX tip from the document?', '[{"id":"a","text":"Always allow sedation before signing"},{"id":"b","text":"Nurse witnesses explanation and signature"},{"id":"c","text":"Never allow sedated/confused patient to sign"},{"id":"d","text":"Family can interpret if they speak English well"}]'::jsonb, ARRAY['c'], false, 'NCLEX tip: Never allow a sedated or confused patient to sign consent—it is invalid.', 'Informed Consent', 25),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse witnesses consent. Which is NOT part of the witness role?', '[{"id":"a","text":"Verify patient signed voluntarily"},{"id":"b","text":"Verify patient is alert and oriented"},{"id":"c","text":"Provide full explanation of procedure risks"},{"id":"d","text":"Verify patient appears mentally competent"}]'::jsonb, ARRAY['c'], false, 'The witness role does NOT include providing the full explanation—that is the provider''s role.', 'Informed Consent', 26),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which action best demonstrates "patient autonomy" protection?', '[{"id":"a","text":"Persuading patient to agree"},{"id":"b","text":"Ensuring decision is voluntary and free of coercion"},{"id":"c","text":"Limiting patient questions"},{"id":"d","text":"Asking family to decide"}]'::jsonb, ARRAY['b'], false, 'Autonomy is protected by ensuring decisions are voluntary and free of coercion.', 'Informed Consent', 27),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient says: "I feel pressured." The nurse should:', '[{"id":"a","text":"Ignore and proceed"},{"id":"b","text":"Stop the process and alert the provider"},{"id":"c","text":"Ask family why they pressure"},{"id":"d","text":"Have patient sign later without addressing pressure"}]'::jsonb, ARRAY['b'], false, 'Any indication of pressure requires stopping and alerting the provider.', 'Informed Consent', 28),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The patient has a language barrier. Which is correct?', '[{"id":"a","text":"Nurse can interpret if bilingual"},{"id":"b","text":"Family can interpret if they insist"},{"id":"c","text":"Licensed medical interpreter must be used"},{"id":"d","text":"Consent can proceed with gestures"}]'::jsonb, ARRAY['c'], false, 'A licensed medical interpreter must be used for language barriers to ensure accurate understanding.', 'Informed Consent', 29),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which documentation item is MOST legally protective per document?', '[{"id":"a","text":"Nurse wrote \"patient understood\""},{"id":"b","text":"Date/time + education summary + questions/responses + competency verification"},{"id":"c","text":"Only procedure name"},{"id":"d","text":"Only witness signature"}]'::jsonb, ARRAY['b'], false, 'Complete documentation with date/time, education, questions, responses, and competency is most legally protective.', 'Informed Consent', 30),

-- Questions 31-40: Patient Decision-Making & Nurse Response
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient asks nurse: "What do you think I should do?" Best response based on document roles:', '[{"id":"a","text":"Recommend the best option"},{"id":"b","text":"Tell patient the provider decides"},{"id":"c","text":"Encourage patient questions and notify provider to clarify, supporting understanding and right to refuse"},{"id":"d","text":"Ask family to answer"}]'::jsonb, ARRAY['c'], false, 'The nurse encourages questions, notifies the provider, and supports the patient''s understanding and right to refuse.', 'Informed Consent', 31),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse sees the patient signed but looks confused. What should the nurse do?', '[{"id":"a","text":"Accept signature; it''s done"},{"id":"b","text":"Notify provider because consent may be incomplete/unclear"},{"id":"c","text":"File the consent and proceed"},{"id":"d","text":"Have the nurse rewrite the consent"}]'::jsonb, ARRAY['b'], false, 'If the patient looks confused after signing, the consent may be invalid—notify the provider.', 'Informed Consent', 32),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse is asked to "obtain" consent. Correct action?', '[{"id":"a","text":"Obtain it if provider approved"},{"id":"b","text":"Obtain it if patient already agreed"},{"id":"c","text":"Refuse; only provider obtains informed consent"},{"id":"d","text":"Obtain it only for low-risk procedures"}]'::jsonb, ARRAY['c'], false, 'The nurse must refuse to obtain consent—only the provider may obtain informed consent.', 'Informed Consent', 33),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The patient is awake and oriented but hesitant. Nurse should:', '[{"id":"a","text":"Witness signature quickly"},{"id":"b","text":"Stop and notify provider of doubt/hesitancy"},{"id":"c","text":"Ask family to help decide"},{"id":"d","text":"Proceed because patient is competent"}]'::jsonb, ARRAY['b'], false, 'Hesitancy requires stopping and notifying the provider, even if the patient is competent.', 'Informed Consent', 34),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which scenario requires the nurse to stop the consent process immediately?', '[{"id":"a","text":"Patient asks a question"},{"id":"b","text":"Patient is smiling"},{"id":"c","text":"Patient is sedated/confused"},{"id":"d","text":"Patient requests visual aids"}]'::jsonb, ARRAY['c'], false, 'Sedation or confusion invalidates consent—the process must stop immediately.', 'Informed Consent', 35),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is an example of "reinforce provider explanation"?', '[{"id":"a","text":"Nurse creates new risk list not discussed"},{"id":"b","text":"Nurse repeats what provider said and checks understanding"},{"id":"c","text":"Nurse obtains signature without provider involvement"},{"id":"d","text":"Nurse asks family to explain risks"}]'::jsonb, ARRAY['b'], false, 'Reinforcing means repeating what the provider said and checking patient understanding.', 'Informed Consent', 36),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient says: "I still don''t understand benefits." Nurse should:', '[{"id":"a","text":"Explain benefits fully independently"},{"id":"b","text":"Tell patient benefits are obvious"},{"id":"c","text":"Notify provider for clarification and encourage questions"},{"id":"d","text":"Ask another patient to explain"}]'::jsonb, ARRAY['c'], false, 'Unanswered questions require notifying the provider for clarification.', 'Informed Consent', 37),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which role includes "ensure patient feels safe to ask questions"?', '[{"id":"a","text":"Witness only"},{"id":"b","text":"Advocate"},{"id":"c","text":"Provider role"},{"id":"d","text":"Unit clerk"}]'::jsonb, ARRAY['b'], false, 'The advocate role includes creating a safe environment for patient questions.', 'Informed Consent', 38),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient is oriented but under opioids. Consent is:', '[{"id":"a","text":"Valid if patient is cooperative"},{"id":"b","text":"Invalid per document"},{"id":"c","text":"Valid if family agrees"},{"id":"d","text":"Valid if nurse witnesses"}]'::jsonb, ARRAY['b'], false, 'Consent under opioids is invalid, even if the patient appears oriented.', 'Informed Consent', 39),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Nurse witnesses signature. What is the nurse NOT witnessing?', '[{"id":"a","text":"Voluntary nature"},{"id":"b","text":"Mental competence appearance"},{"id":"c","text":"Provider explanation"},{"id":"d","text":"Alert/oriented state"}]'::jsonb, ARRAY['c'], false, 'The nurse witnesses the signature, voluntary nature, and competency—not the provider''s explanation itself.', 'Informed Consent', 40),

-- Questions 41-50: Critical NCLEX Scenarios
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which indicates nurse must notify provider?', '[{"id":"a","text":"Patient has no questions"},{"id":"b","text":"Patient asks questions"},{"id":"c","text":"Patient doesn''t understand after reinforcement"},{"id":"d","text":"Patient is calm"}]'::jsonb, ARRAY['c'], false, 'If the patient does not understand after nursing reinforcement, the provider must be notified.', 'Informed Consent', 41),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is a correct NCLEX rule from document?', '[{"id":"a","text":"Nurse should persuade patient to sign"},{"id":"b","text":"Nurse must stop if patient expresses misunderstanding"},{"id":"c","text":"Nurse can interpret if family refuses interpreter"},{"id":"d","text":"Nurse obtains consent if provider is absent"}]'::jsonb, ARRAY['b'], false, 'NCLEX rule: Nurse must stop the process if patient expresses misunderstanding or confusion.', 'Informed Consent', 42),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Minor (<18) consent requirement:', '[{"id":"a","text":"Patient can sign always"},{"id":"b","text":"Guardian required (exceptions exist)"},{"id":"c","text":"Nurse can sign"},{"id":"d","text":"Consent not needed"}]'::jsonb, ARRAY['b'], false, 'Guardian consent is required for minors, with exceptions for emancipated minors and emergencies.', 'Informed Consent', 43),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Emergency implied consent applies when:', '[{"id":"a","text":"Patient is awake and refusing"},{"id":"b","text":"Patient is unconscious and no surrogate available"},{"id":"c","text":"Patient is confused but family is present"},{"id":"d","text":"Patient is hesitant"}]'::jsonb, ARRAY['b'], false, 'Implied consent applies when patient is unconscious and no surrogate decision-maker is available.', 'Informed Consent', 44),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse provides educational materials. Which role?', '[{"id":"a","text":"Witness"},{"id":"b","text":"Educator"},{"id":"c","text":"Provider"},{"id":"d","text":"Legal counsel"}]'::jsonb, ARRAY['b'], false, 'Providing educational materials is part of the nurse educator role.', 'Informed Consent', 45),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse sees the consent form is incomplete. Best action?', '[{"id":"a","text":"Fill it out"},{"id":"b","text":"Ask patient to sign anyway"},{"id":"c","text":"Notify provider because consent is incomplete/unclear"},{"id":"d","text":"Have family complete it"}]'::jsonb, ARRAY['c'], false, 'An incomplete consent form must be addressed by the provider before proceeding.', 'Informed Consent', 46),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse''s primary legal boundary is:', '[{"id":"a","text":"Never discuss anything with patient"},{"id":"b","text":"Do not obtain informed consent; provider role only"},{"id":"c","text":"Never witness signatures"},{"id":"d","text":"Only document date/time"}]'::jsonb, ARRAY['b'], false, 'The nurse''s primary legal boundary is not obtaining informed consent—that is the provider''s exclusive role.', 'Informed Consent', 47),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which action best supports "right to refuse"?', '[{"id":"a","text":"Minimizing patient concerns"},{"id":"b","text":"Rushing the signature"},{"id":"c","text":"Advocating for understanding and acknowledging refusal is allowed"},{"id":"d","text":"Asking family to decide"}]'::jsonb, ARRAY['c'], false, 'Supporting the right to refuse means advocating for patient understanding and acknowledging their right to decline.', 'Informed Consent', 48),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient expresses doubt. Nurse should FIRST:', '[{"id":"a","text":"Witness signature to avoid delay"},{"id":"b","text":"Tell patient doubt is normal"},{"id":"c","text":"Stop the process and notify provider"},{"id":"d","text":"Ask family to reassure"}]'::jsonb, ARRAY['c'], false, 'Any expression of doubt requires immediately stopping and notifying the provider.', 'Informed Consent', 49),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which statement is most correct?', '[{"id":"a","text":"Nurse explains procedure; provider witnesses"},{"id":"b","text":"Provider obtains consent; nurse witnesses signature"},{"id":"c","text":"Family interprets; nurse documents only"},{"id":"d","text":"Nurse obtains consent if provider is present"}]'::jsonb, ARRAY['b'], false, 'Correct roles: Provider obtains informed consent by explaining procedure/risks/benefits/alternatives; nurse witnesses the signature.', 'Informed Consent', 50),

-- Questions 51-60: Emotional State & Verification
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient signs consent but appears fearful and tearful. What is the nurse''s priority action?', '[{"id":"a","text":"Proceed because signature is complete"},{"id":"b","text":"Notify provider due to possible coercion or misunderstanding"},{"id":"c","text":"Ask family to reassure patient"},{"id":"d","text":"File consent form"}]'::jsonb, ARRAY['b'], false, 'Fearful and tearful behavior may indicate coercion or misunderstanding. The nurse must notify the provider.', 'Informed Consent', 51),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse witnesses a signature but did not see the provider explain the procedure. The nurse should:', '[{"id":"a","text":"Assume explanation occurred"},{"id":"b","text":"Witness anyway"},{"id":"c","text":"Confirm explanation occurred before witnessing"},{"id":"d","text":"Re-explain the procedure"}]'::jsonb, ARRAY['c'], false, 'The nurse must confirm that the provider explanation occurred before witnessing the signature.', 'Informed Consent', 52),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which finding invalidates consent?', '[{"id":"a","text":"Patient nervous"},{"id":"b","text":"Patient anxious"},{"id":"c","text":"Patient confused"},{"id":"d","text":"Patient quiet"}]'::jsonb, ARRAY['c'], false, 'Confusion indicates lack of mental competency and invalidates consent.', 'Informed Consent', 53),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse hears a family member answering all questions for the patient. The nurse should:', '[{"id":"a","text":"Accept family''s answers"},{"id":"b","text":"Redirect questions to the patient to ensure autonomy"},{"id":"c","text":"Allow family to decide"},{"id":"d","text":"Ask provider to hurry"}]'::jsonb, ARRAY['b'], false, 'The patient must answer questions independently to demonstrate understanding and preserve autonomy.', 'Informed Consent', 54),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient says: "I trust you, just tell me what to do." The nurse should:', '[{"id":"a","text":"Recommend the procedure"},{"id":"b","text":"Reinforce provider explanation and support patient decision-making"},{"id":"c","text":"Decide for patient"},{"id":"d","text":"Tell family to decide"}]'::jsonb, ARRAY['b'], false, 'The nurse supports the patient in making their own decision by reinforcing education, not making the decision for them.', 'Informed Consent', 55),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is NOT part of informed consent per document?', '[{"id":"a","text":"Risks"},{"id":"b","text":"Benefits"},{"id":"c","text":"Nurse opinion"},{"id":"d","text":"Alternatives"}]'::jsonb, ARRAY['c'], false, 'Informed consent includes procedure, risks, benefits, and alternatives—not the nurse''s personal opinion.', 'Informed Consent', 56),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient signs while mildly sedated but oriented. The nurse should:', '[{"id":"a","text":"Accept signature"},{"id":"b","text":"Stop and notify provider because sedation invalidates consent"},{"id":"c","text":"Ask family to confirm"},{"id":"d","text":"Proceed if provider agrees"}]'::jsonb, ARRAY['b'], false, 'Any sedation, even if patient appears oriented, invalidates consent due to impaired decision-making.', 'Informed Consent', 57),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse documents: "Patient understands completely." This is:', '[{"id":"a","text":"Appropriate"},{"id":"b","text":"Required"},{"id":"c","text":"Inappropriate unless supported by documented assessment and summary"},{"id":"d","text":"Optional"}]'::jsonb, ARRAY['c'], false, 'Vague statements are inappropriate. Documentation must include specific assessment details and summary of understanding.', 'Informed Consent', 58),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient states: "I feel rushed." The nurse should:', '[{"id":"a","text":"Continue process"},{"id":"b","text":"Pause and advocate for adequate time"},{"id":"c","text":"Tell patient procedure must proceed"},{"id":"d","text":"Ask family to reassure"}]'::jsonb, ARRAY['b'], false, 'Feeling rushed compromises voluntariness. The nurse must pause and advocate for adequate time.', 'Informed Consent', 59),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The most important element of voluntariness is absence of:', '[{"id":"a","text":"Questions"},{"id":"b","text":"Fear"},{"id":"c","text":"Coercion"},{"id":"d","text":"Anxiety"}]'::jsonb, ARRAY['c'], false, 'Voluntariness requires the absence of coercion or pressure. Some fear and anxiety are normal.', 'Informed Consent', 60),

-- Questions 61-70: Patient Rights & Refusal
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'If a patient refuses after signing consent, the nurse should:', '[{"id":"a","text":"Ignore refusal"},{"id":"b","text":"Notify provider immediately"},{"id":"c","text":"Tell patient refusal is invalid"},{"id":"d","text":"Ask family to override"}]'::jsonb, ARRAY['b'], false, 'Patients have the right to withdraw consent at any time. The provider must be notified immediately.', 'Informed Consent', 61),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse''s role when patient is hesitant includes:', '[{"id":"a","text":"Persuasion"},{"id":"b","text":"Advocacy"},{"id":"c","text":"Decision-making"},{"id":"d","text":"Procedure explanation"}]'::jsonb, ARRAY['b'], false, 'When a patient is hesitant, the nurse acts as advocate to ensure understanding and voluntary decision-making.', 'Informed Consent', 62),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient is alert but intoxicated. Consent is:', '[{"id":"a","text":"Valid"},{"id":"b","text":"Invalid due to impaired decision-making"},{"id":"c","text":"Valid with family"},{"id":"d","text":"Valid if signed"}]'::jsonb, ARRAY['b'], false, 'Intoxication impairs decision-making capacity, making consent invalid even if patient appears alert.', 'Informed Consent', 63),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which ensures legal protection?', '[{"id":"a","text":"Signature alone"},{"id":"b","text":"Provider explanation alone"},{"id":"c","text":"Proper documentation including competency and voluntariness"},{"id":"d","text":"Family presence"}]'::jsonb, ARRAY['c'], false, 'Legal protection requires complete documentation of competency assessment, voluntariness, and education.', 'Informed Consent', 64),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse witnesses consent but notes patient cannot repeat procedure purpose. Action?', '[{"id":"a","text":"Witness anyway"},{"id":"b","text":"Notify provider"},{"id":"c","text":"Ask family to clarify"},{"id":"d","text":"Explain and proceed"}]'::jsonb, ARRAY['b'], false, 'If patient cannot repeat procedure purpose, understanding is questionable. Provider must be notified.', 'Informed Consent', 65),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient asks about a rare complication not discussed. Nurse should:', '[{"id":"a","text":"Provide independent explanation"},{"id":"b","text":"Notify provider for clarification"},{"id":"c","text":"Say it''s unimportant"},{"id":"d","text":"Ignore question"}]'::jsonb, ARRAY['b'], false, 'Questions about complications not discussed by the provider require provider clarification.', 'Informed Consent', 66),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which demonstrates the nurse acting as advocate?', '[{"id":"a","text":"Minimizing concerns"},{"id":"b","text":"Encouraging signature"},{"id":"c","text":"Ensuring patient right to refuse is respected"},{"id":"d","text":"Deciding treatment"}]'::jsonb, ARRAY['c'], false, 'Advocacy includes respecting and protecting the patient''s right to refuse treatment.', 'Informed Consent', 67),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient signs while crying and shaking. Nurse''s first step:', '[{"id":"a","text":"Witness signature"},{"id":"b","text":"Stop and reassess voluntariness"},{"id":"c","text":"Call family"},{"id":"d","text":"File consent"}]'::jsonb, ARRAY['b'], false, 'Crying and shaking may indicate emotional distress or lack of voluntariness. Reassessment is required.', 'Informed Consent', 68),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'If provider delegates consent explanation to nurse, nurse should:', '[{"id":"a","text":"Accept delegation"},{"id":"b","text":"Refuse because only provider obtains informed consent"},{"id":"c","text":"Explain risks independently"},{"id":"d","text":"Ask CNA to help"}]'::jsonb, ARRAY['b'], false, 'The nurse must refuse delegation. Only the provider can obtain informed consent.', 'Informed Consent', 69),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient does not speak English and declines interpreter. The nurse should:', '[{"id":"a","text":"Respect refusal and proceed"},{"id":"b","text":"Use family interpreter"},{"id":"c","text":"Explain need for licensed interpreter to ensure valid consent"},{"id":"d","text":"Have provider sign"}]'::jsonb, ARRAY['c'], false, 'A licensed interpreter is required for valid consent. The nurse must explain this necessity.', 'Informed Consent', 70),

-- Questions 71-80: Documentation & Boundaries
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse notes consent form missing risk section. Action?', '[{"id":"a","text":"Ignore"},{"id":"b","text":"Fill it in"},{"id":"c","text":"Notify provider because consent incomplete"},{"id":"d","text":"Ask patient to sign anyway"}]'::jsonb, ARRAY['c'], false, 'An incomplete consent form must be corrected by the provider before proceeding.', 'Informed Consent', 71),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient appears pressured by spouse. Which role is primary?', '[{"id":"a","text":"Witness"},{"id":"b","text":"Educator"},{"id":"c","text":"Advocate"},{"id":"d","text":"Recorder"}]'::jsonb, ARRAY['c'], false, 'When pressure is suspected, the advocate role is primary to ensure voluntary decision-making.', 'Informed Consent', 72),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The patient asks: "What happens if I don''t sign?" Nurse should:', '[{"id":"a","text":"Explain consequences independently"},{"id":"b","text":"Support patient''s right to refuse and notify provider"},{"id":"c","text":"Encourage signing"},{"id":"d","text":"Avoid answering"}]'::jsonb, ARRAY['b'], false, 'The nurse supports the right to refuse and notifies the provider to explain consequences.', 'Informed Consent', 73),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which indicates patient competency?', '[{"id":"a","text":"Calm appearance"},{"id":"b","text":"Alert and oriented"},{"id":"c","text":"Family agreement"},{"id":"d","text":"Signed paper"}]'::jsonb, ARRAY['b'], false, 'Competency is indicated by being alert and oriented, not appearance or signatures.', 'Informed Consent', 74),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which scenario requires stopping consent immediately?', '[{"id":"a","text":"Patient yawns"},{"id":"b","text":"Patient confused"},{"id":"c","text":"Patient asks questions"},{"id":"d","text":"Patient smiles"}]'::jsonb, ARRAY['b'], false, 'Confusion invalidates consent and requires immediately stopping the process.', 'Informed Consent', 75),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Nurse documentation must include:', '[{"id":"a","text":"Only signature"},{"id":"b","text":"Nurse opinion"},{"id":"c","text":"Date/time + summary + questions + competency"},{"id":"d","text":"Family comments only"}]'::jsonb, ARRAY['c'], false, 'Complete documentation includes date/time, education summary, questions addressed, and competency assessment.', 'Informed Consent', 76),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient says "I feel forced." Nurse should:', '[{"id":"a","text":"Proceed"},{"id":"b","text":"Notify provider"},{"id":"c","text":"Ignore"},{"id":"d","text":"Ask family to explain"}]'::jsonb, ARRAY['b'], false, 'Any statement indicating feeling forced compromises voluntariness and requires provider notification.', 'Informed Consent', 77),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse cannot:', '[{"id":"a","text":"Reinforce explanation"},{"id":"b","text":"Encourage questions"},{"id":"c","text":"Obtain informed consent"},{"id":"d","text":"Witness signature"}]'::jsonb, ARRAY['c'], false, 'The nurse cannot obtain informed consent—that is the provider''s exclusive role.', 'Informed Consent', 78),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which best supports ethical autonomy?', '[{"id":"a","text":"Family decision"},{"id":"b","text":"Patient voluntary decision"},{"id":"c","text":"Nurse recommendation"},{"id":"d","text":"Provider pressure"}]'::jsonb, ARRAY['b'], false, 'Autonomy is best supported by the patient making their own voluntary decision without external pressure.', 'Informed Consent', 79),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient signs but later says they misunderstood risks. Nurse should:', '[{"id":"a","text":"Ignore"},{"id":"b","text":"Notify provider immediately"},{"id":"c","text":"Tell patient it''s too late"},{"id":"d","text":"Ask family"}]'::jsonb, ARRAY['b'], false, 'Misunderstanding of risks invalidates consent even after signing. Provider must be notified immediately.', 'Informed Consent', 80),

-- Questions 81-90: Competency & Validity Assessment
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which patient can legally sign?', '[{"id":"a","text":"Confused"},{"id":"b","text":"Sedated"},{"id":"c","text":"Alert, competent, voluntary"},{"id":"d","text":"Intoxicated"}]'::jsonb, ARRAY['c'], false, 'Valid consent requires the patient to be alert, competent, and signing voluntarily without coercion.', 'Informed Consent', 81),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Nurse witnesses signature but patient was not oriented earlier. Action?', '[{"id":"a","text":"Accept"},{"id":"b","text":"Reassess orientation before witnessing"},{"id":"c","text":"Ignore"},{"id":"d","text":"Ask CNA"}]'::jsonb, ARRAY['b'], false, 'Current orientation must be verified before witnessing. Reassessment is required.', 'Informed Consent', 82),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'What makes consent ethically valid?', '[{"id":"a","text":"Signature"},{"id":"b","text":"Provider presence"},{"id":"c","text":"Understanding + voluntariness + competency"},{"id":"d","text":"Family agreement"}]'::jsonb, ARRAY['c'], false, 'Ethical validity requires understanding, voluntariness, and competency—not just a signature.', 'Informed Consent', 83),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient hesitant but signs quickly. Nurse should:', '[{"id":"a","text":"Accept signature"},{"id":"b","text":"Pause and reassess voluntariness"},{"id":"c","text":"File consent"},{"id":"d","text":"Ignore"}]'::jsonb, ARRAY['b'], false, 'Hesitancy followed by quick signing may indicate pressure. Voluntariness must be reassessed.', 'Informed Consent', 84),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A patient wants family to decide. Nurse should:', '[{"id":"a","text":"Encourage autonomy"},{"id":"b","text":"Accept family decision automatically"},{"id":"c","text":"Decide for patient"},{"id":"d","text":"Ignore"}]'::jsonb, ARRAY['a'], false, 'The nurse should encourage patient autonomy and independent decision-making when appropriate.', 'Informed Consent', 85),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which invalidates consent?', '[{"id":"a","text":"Anxiety"},{"id":"b","text":"Nervousness"},{"id":"c","text":"Coercion"},{"id":"d","text":"Silence"}]'::jsonb, ARRAY['c'], false, 'Coercion invalidates consent by compromising voluntariness. Some anxiety/nervousness is normal.', 'Informed Consent', 86),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient under anesthesia cannot consent because:', '[{"id":"a","text":"Fear"},{"id":"b","text":"Lack of voluntariness"},{"id":"c","text":"Lack of competency due to sedation"},{"id":"d","text":"Time constraint"}]'::jsonb, ARRAY['c'], false, 'Anesthesia/sedation eliminates competency, making consent impossible.', 'Informed Consent', 87),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Nurse''s first step if unsure about validity:', '[{"id":"a","text":"Witness anyway"},{"id":"b","text":"Notify provider"},{"id":"c","text":"Ignore"},{"id":"d","text":"Ask family"}]'::jsonb, ARRAY['b'], false, 'When in doubt about consent validity, the nurse must notify the provider.', 'Informed Consent', 88),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Interpreter ensures:', '[{"id":"a","text":"Faster process"},{"id":"b","text":"Legal compliance and accurate understanding"},{"id":"c","text":"Nurse convenience"},{"id":"d","text":"Family involvement"}]'::jsonb, ARRAY['b'], false, 'Professional interpreters ensure legal compliance and accurate patient understanding.', 'Informed Consent', 89),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'The nurse must verify:', '[{"id":"a","text":"Provider explained procedure"},{"id":"b","text":"Nurse explained procedure"},{"id":"c","text":"Family explained"},{"id":"d","text":"CNA explained"}]'::jsonb, ARRAY['a'], false, 'The nurse verifies that the provider (not nurse, family, or CNA) explained the procedure.', 'Informed Consent', 90),

-- Questions 91-100: Critical Decision Points
('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient says "I changed my mind." Nurse should:', '[{"id":"a","text":"Respect decision and notify provider"},{"id":"b","text":"Encourage proceeding"},{"id":"c","text":"Ignore"},{"id":"d","text":"Ask family"}]'::jsonb, ARRAY['a'], false, 'The patient has the right to withdraw consent. The nurse respects this and notifies the provider.', 'Informed Consent', 91),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Consent must be:', '[{"id":"a","text":"Quick"},{"id":"b","text":"Signed"},{"id":"c","text":"Voluntary"},{"id":"d","text":"Silent"}]'::jsonb, ARRAY['c'], false, 'The most essential element of valid consent is that it must be voluntary.', 'Informed Consent', 92),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'If patient expresses doubt AFTER signing:', '[{"id":"a","text":"Ignore"},{"id":"b","text":"Notify provider immediately"},{"id":"c","text":"Continue"},{"id":"d","text":"Ask CNA"}]'::jsonb, ARRAY['b'], false, 'Doubt expressed after signing may indicate invalid consent. Provider must be notified immediately.', 'Informed Consent', 93),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Nurse reinforcing explanation should:', '[{"id":"a","text":"Add new risks not discussed"},{"id":"b","text":"Repeat and clarify provider''s information"},{"id":"c","text":"Replace provider"},{"id":"d","text":"Decide"}]'::jsonb, ARRAY['b'], false, 'Reinforcement means repeating and clarifying what the provider said, not adding new information.', 'Informed Consent', 94),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'A confused patient signs. Nurse witnesses. This is:', '[{"id":"a","text":"Valid"},{"id":"b","text":"Invalid"},{"id":"c","text":"Optional"},{"id":"d","text":"Legal"}]'::jsonb, ARRAY['b'], false, 'A confused patient lacks competency. Witnessing such a signature results in invalid consent.', 'Informed Consent', 95),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is nurse boundary violation?', '[{"id":"a","text":"Encouraging questions"},{"id":"b","text":"Obtaining consent"},{"id":"c","text":"Witnessing signature"},{"id":"d","text":"Using interpreter"}]'::jsonb, ARRAY['b'], false, 'Obtaining informed consent violates nurse boundaries—that is the provider''s exclusive role.', 'Informed Consent', 96),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which demonstrates advocacy?', '[{"id":"a","text":"Speeding process"},{"id":"b","text":"Ignoring confusion"},{"id":"c","text":"Ensuring patient feels safe asking questions"},{"id":"d","text":"Persuading patient"}]'::jsonb, ARRAY['c'], false, 'Advocacy includes creating a safe environment where patients feel comfortable asking questions.', 'Informed Consent', 97),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Patient appears pressured. Nurse should:', '[{"id":"a","text":"Proceed"},{"id":"b","text":"Assess voluntariness and notify provider"},{"id":"c","text":"Ask family"},{"id":"d","text":"Ignore"}]'::jsonb, ARRAY['b'], false, 'Signs of pressure require assessment of voluntariness and provider notification.', 'Informed Consent', 98),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Incomplete consent form requires:', '[{"id":"a","text":"Nurse correction"},{"id":"b","text":"Provider notification"},{"id":"c","text":"Family signature"},{"id":"d","text":"Immediate filing"}]'::jsonb, ARRAY['b'], false, 'An incomplete form must be corrected by the provider, not the nurse.', 'Informed Consent', 99),

('00000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Which is the most accurate statement?', '[{"id":"a","text":"Nurse obtains consent"},{"id":"b","text":"Provider obtains consent; nurse witnesses and advocates"},{"id":"c","text":"Family interprets always"},{"id":"d","text":"Consent valid under sedation"}]'::jsonb, ARRAY['b'], false, 'The provider obtains informed consent. The nurse witnesses the signature and advocates for the patient.', 'Informed Consent', 100);

-- ============================================
-- VERIFICATION
-- ============================================

-- Show total question count for Nurse's Role in Informed Consent topic
SELECT 
  t.name as topic_name,
  COUNT(q.id) as total_questions
FROM test_topics t
LEFT JOIN test_questions q ON q.topic_id = t.id 
  AND q.test_id = '00000000-0000-0000-0000-000000000001'
WHERE t.id = '20000000-0000-0000-0000-000000000002'
GROUP BY t.id, t.name;
-- Expected: Nurse's Role in Informed Consent with 100 questions

-- Verify display_order range
SELECT 
  MIN(display_order) as first_question,
  MAX(display_order) as last_question,
  COUNT(*) as total_count
FROM test_questions 
WHERE test_id = '00000000-0000-0000-0000-000000000001'
  AND topic_id = '20000000-0000-0000-0000-000000000002';
-- Expected: 1 to 100, count = 100
